/bin/bash -lc "cat > dist/presentation.css <<'EOF'
.sheet {
  max-inline-size: 42rem;
  margin: clamp(1rem, 5vw, 3rem) auto;
  inline-size: calc(100% - 2 * var(--gap));
  padding: clamp(var(--gap), 4vw, 2rem);
  border-radius: var(--radius);
  background: var(--paper);
  line-height: 1.5;
}

.sheet h1 {
  margin: 0;
  font-size: clamp(1.5rem, 3vw, 1.875rem);
  line-height: 1.2;
}

.sheet h1 + p {
  margin: 0.5rem 0 1.5rem;
  color: var(--subtle);
}

.sheet label {
  display: block;
  margin-block-end: 0.375rem;
  font-weight: 600;
}

.sheet input + label {
  margin-block-start: var(--gap);
}

.sheet input,
.sheet select {
  display: block;
  inline-size: 100%;
  min-block-size: 44px;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-block-start: 1.5rem;
}

.sheet button {
  min-inline-size: 0;
  max-inline-size: 100%;
  min-block-size: 44px;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--subtle);
  font-weight: 600;
  line-height: 1.35;
  white-space: normal;
  overflow-wrap: anywhere;
}

.sheet button:hover {
  background: var(--canvas);
}

.sheet [data-primary],
.sheet #confirm {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--paper);
}

.sheet [data-primary]:hover,
.sheet #confirm:hover {
  border-color: var(--ink);
  background: var(--ink);
}

.sheet :is(button, input, select):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sheet input[aria-invalid=\"true\"] {
  border-color: var(--danger);
}

.sheet [role=\"alert\"] {
  margin: var(--gap) 0 0;
  padding: 0.75rem;
  border-inline-start: 3px solid var(--danger);
  border-radius: 0 var(--radius) var(--radius) 0;
  background: color-mix(in srgb, var(--danger) 7%, var(--paper));
  color: var(--danger);
  font-weight: 600;
}

.sheet [role=\"status\"] {
  margin: 1.5rem 0 0;
  padding-block-start: var(--gap);
  border-block-start: 1px solid var(--line);
  color: var(--subtle);
  overflow-wrap: anywhere;
}

.sheet dialog {
  max-inline-size: min(28rem, calc(100% - 2 * var(--gap)));
  padding: clamp(var(--gap), 4vw, 1.5rem);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.sheet dialog h2 {
  margin: 0;
  font-size: 1.25rem;
  line-height: 1.25;
}

.sheet dialog p {
  margin: 0.5rem 0 var(--gap);
}

@media (max-width: 36rem) {
  .actions {
    flex-direction: column;
  }
}
EOF"

