/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const load = name => {
  const result = JSON.parse(readFileSync('visits/' + name + '.json'));
  assert.equal(result.error,null);
  return result.timeline.slice(1).map(({state})=>state);
};
const wide=load('c4b98808-2007-4558-8c7c-6d792749a482');
const narrow=load('404cd3e7-79f0-4664-ab73-9abc4c3ddb73');
const modal=load('2a7db0fd-f6d4-4f70-82e8-0fa6a8ca6afd');
const primary = 'Review proposed notification preferences';
const secondary = 'Restore saved values';
const buttons = s => s.geometry.elements.filter(e => [primary,secondary].includes(e.text) && e.tag==='BUTTON');
for (const [states,width] of [[wide,1180],[narrow,390],[modal,390]]) {
  for (const s of states) {
    assert.equal(s.geometry.viewport,width);
    assert.equal(s.geometry.page,width);
    assert.equal(buttons(s).length,2);
    for (const e of buttons(s)) {
      assert.equal(e.scroll,e.client);
      assert(e.x >= 0 && e.x+e.w <= width && e.h >= 44);
    }
  }
}
assert.equal(buttons(wide[0])[0].h,44);
assert(buttons(narrow[0])[0].h > 44);
assert.deepEqual(narrow.slice(1,5).map(s=>s.focus.id??s.focus.text), ['email','rate',primary,secondary]);
assert.equal(buttons(narrow[3])[0].outline,'solid 2px');
assert.equal(buttons(narrow[4])[1].outline,'solid 2px');
assert.equal(narrow[6].fields[0].invalid,'true');
assert.equal(narrow[6].focus.id,'email');
assert.equal(narrow[6].status[0],'Enter a complete email address before reviewing these settings.');
assert.equal(narrow[7].fields[0].value,'ops@example.test');
assert.equal(narrow[7].fields[0].invalid,'false');
assert("'!narrow[7].status.some(s=>s.startsWith('"'Enter')));
assert.equal(narrow[8].focus.id,'cancel');
assert.equal(narrow[9].focus.id,'confirm');
assert.equal(narrow[10].dialog.length,0);
assert.equal(narrow[10].focus.text,primary);
assert.match(wide[4].dialog[0],/Review notification settings/);
assert.equal(wide[5].dialog.length,0);
assert.equal(wide[5].status[0],'ops@example.test / Daily');
assert.equal(wide[7].dialog.length,0);
assert.equal(wide[7].focus.text,primary);
assert.equal(wide[9].dialog.length,0);
assert.equal(wide[9].status[0],'duty@example.test / Daily');
assert.equal(modal[2].focus.id,'confirm');
function luminance(rgb) {
  return rgb.map(n=>n/255).map(n=>n<=0.04045?n/12.92:((n+0.055)/1.055)**2.4)
    .reduce((total,n,i)=>total+n*[0.2126,0.7152,0.0722][i],0)
}
const mix=(a,b,p)=>a.map((n,i)=>n*p+b[i]*(1-p));
const white=[255,255,255], accent=[36,85,120], danger=[142,45,40];
for (const [label,fore,back,min] of [
  ['Primary/focus', accent, white, 4.5],
  ['Field border', mix([151,170,181],[52,77,92],0.7), white, 3],
  ['Error text', danger, mix(danger,white,0.07), 4.5],
]) {
  const contrast=(luminance(back)+0.05)/(luminance(fore)+0.05);
  assert(contrast >= min);
  console.log(label,contrast.toFixed(2));
}
console.log('Verified geometry, focus sequence, error recovery, preview, cancellation and confirmation.');
EOF
